export function t(lang, key, vars) {
  const table = STRINGS[lang] || STRINGS.zh;
  let s = table[key];
  if (s === undefined) s = STRINGS.zh[key];
  if (s === undefined) return key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      s = s.split("{" + k + "}").join(String(v));
    }
  }
  return s;
}

export function catLabel(lang, cat) {
  return t(lang, "cat." + cat);
}

export function riskLabel(lang, risk) {
  return t(lang, "risk." + risk);
}

/** Detect a sensible initial language from the stored value / browser. */
export function detectLang() {
  try {
    const stored = localStorage.getItem("spacerrecycle.lang");
    if (stored && LANGS.includes(stored)) return stored;
  } catch (_) { /* storage unavailable */ }
  try {
    if (typeof navigator !== "undefined" && navigator.language) {
      const l = navigator.language.toLowerCase();
      if (l.startsWith("zh")) return "zh";
      if (l.startsWith("en")) return "en";
    }
  } catch (_) { /* no navigator */ }
  return "zh";
}
